from tinydb import TinyDB
from tinydb.table import Document
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');value=t.insert(Document({'v':'old'},doc_id=5));print('inserted_identity',value);assert value==5
try:
 t.insert(Document({'v':'new'},doc_id=5))
except ValueError:
 assert t.get(doc_id=5)=={'v':'old'}
else:
 raise AssertionError('duplicate identity overwrote existing document')

from tinydb import TinyDB,where
from tinydb.table import Document
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');t.insert({'name':'old'});value=t.upsert({'name':'new'},where('name')=='new');print('upsert_insert_transition',value,t.all())
assert value==[2] and t.get(doc_id=2)=={'name':'new'}
value=t.upsert(Document({'name':'explicit'},doc_id=7));assert value==[7] and t.get(doc_id=7)=={'name':'explicit'}

from tinydb import TinyDB,where
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');ids=t.insert_multiple([{'n':1},{'n':2},{'n':3}]);removed=t.remove(where('n')==2);print('removed_subset',removed,t.all())
assert removed==[ids[1]] and t.all()==[{'n':1},{'n':3}]
try:
 t.remove(doc_ids=[999])
except KeyError:
 print('absent_id_rejected',True)
else:
 raise AssertionError('absent ID silently ignored')

from tinydb.utils import LRUCache
c=LRUCache(3);payload=['value'];c['key']=payload;value=c['key'];print('cache_value_channel',value);assert value is payload
try:
 c['missing']
except KeyError:
 print('missing_cache_key_rejected',True)
else:
 raise AssertionError('missing key returned a value')
